// Hand-authored store extensions for the Indeed CLI (no "Generated by CLI
// Printing Press" header, so this file survives `generate --force` and
// regen-merge). It lives in package store so it can reuse the unexported
// ftsRowID used by the generated upsert path — keeping FTS-index deletes
// consistent with inserts.
package store

import "context"

// DeleteResource removes a row from both the resources table and its
// resources_fts index entry, keyed by the same rowid scheme the generated
// Upsert path uses. Use this instead of a bare `DELETE FROM resources` so
// deletes don't leave orphaned FTS rows behind.
func (s *Store) DeleteResource(ctx context.Context, resourceType, id string) error {
	if _, err := s.db.ExecContext(ctx,
		`DELETE FROM resources WHERE resource_type = ? AND id = ?`,
		resourceType, id); err != nil {
		return err
	}
	// FTS5 (modernc.org/sqlite) deletes by explicit rowid, matching the insert
	// path in upsertGenericResourceTx.
	_, err := s.db.ExecContext(ctx,
		`DELETE FROM resources_fts WHERE rowid = ?`,
		ftsRowID(resourceType, id))
	return err
}

// ListAll returns every stored resource of a type with no row cap, ordered by
// most-recently updated. Use for local aggregations (e.g. company summaries)
// that must see the full set rather than a truncated window.
func (s *Store) ListAll(ctx context.Context, resourceType string) ([][]byte, error) {
	rows, err := s.db.QueryContext(ctx,
		`SELECT data FROM resources WHERE resource_type = ? ORDER BY updated_at DESC`,
		resourceType)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out [][]byte
	for rows.Next() {
		var data string
		if err := rows.Scan(&data); err != nil {
			return nil, err
		}
		out = append(out, []byte(data))
	}
	return out, rows.Err()
}
